<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import type {Evidence,JsonObject} from '@/domain/types'
import {rows,numeric,evidenceOf,text} from './model'
import EvidenceLinks from './EvidenceLinks.vue'
const props=defineProps<{data:JsonObject;topN?:number;canRefine?:boolean}>()
defineEmits<{source:[evidence:Evidence];detail:[row:JsonObject];exclude:[word:string]}>()
const query=ref(''),selected=ref<JsonObject|null>(null),top=ref(50),page=ref(1)
const words=computed(()=>rows(props.data.words).map(row=>({...row,word:row.word ?? row.name ?? row.text,count:numeric(row.count ?? row.frequency) ?? 0})).sort((a,b)=>b.count-a.count))
const filtered=computed(()=>words.value.filter(row=>!query.value || String(row.word).includes(query.value)))
const cloud=computed(()=>filtered.value.slice(0,top.value))
const max=computed(()=>Math.max(1,...cloud.value.map(w=>w.count)))
watch(()=>props.topN,value=>{top.value=typeof value==='number' && Number.isInteger(value) && value>=10 && value<=500 ? value : 50},{immediate:true})
const topOptions=computed(()=>[...new Set([30,50,100,200,top.value])].sort((a,b)=>a-b))
const colors=['#3269db','#315778','#297b71','#7358a6','#9c6635']
const shown=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
</script>
<template><div><div class="result-toolbar"><el-input v-model="query" clearable placeholder="查找词语" @input="page=1"/><el-select v-model="top" aria-label="词云展示数量" style="width:160px"><el-option v-for="n in topOptions" :key="n" :value="n" :label="`展示前 ${n} 个词`"/></el-select><span class="muted">共 {{words.length}} 个词 · 点击词语查看来源</span></div><div class="word-layout"><section class="word-cloud" aria-label="高频词云"><button v-for="(word,index) in cloud" :key="String(word.word)" :style="{fontSize:`${16+Math.sqrt(word.count/max)*30}px`,color:colors[index%colors.length]}" @click="selected=word">{{word.word}}</button><el-empty v-if="!cloud.length" description="没有符合条件的词语"/></section><section><el-table :data="shown" stripe @row-click="(row:JsonObject)=>selected=row"><el-table-column prop="word" label="词语"/><el-table-column prop="count" label="出现次数" width="110" sortable/><el-table-column label="来源" width="100"><template #default="{row}"><el-button text type="primary" @click.stop="selected=row">查看语境</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="filtered.length" layout="prev,pager,next" hide-on-single-page/></section></div><el-drawer :model-value="!!selected" :title="selected ? `词语：${selected.word}` : '出现语境'" size="min(620px, 100vw)" @update:model-value="!$event && (selected=null)"><template v-if="selected"><p class="muted">出现 {{selected.count}} 次；词频表示出现次数，不代表风险程度。</p><article v-for="(source,index) in evidenceOf(selected)" :key="index" class="source-card"><strong>{{source.fileName || '来源资料'}}</strong><blockquote v-if="source.quote">{{source.quote}}</blockquote><EvidenceLinks :evidence="[source]" @open="$emit('source',$event)"/></article><el-empty v-if="!evidenceOf(selected).length" description="本条词频未返回来源片段"/><div v-if="canRefine" class="refine-word"><el-button @click="$emit('exclude',String(selected.word))">加入停用词</el-button><p class="muted">带入新草稿，确认后重新统计。</p></div><p v-if="selected.context" class="context">{{text(selected.context)}}</p></template></el-drawer></div></template>
<style scoped>.result-toolbar{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:16px}.result-toolbar .el-input{max-width:280px}.muted{color:#596b80;font-size:14px}.word-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(350px,.8fr);gap:24px}.word-cloud{display:flex;align-content:center;justify-content:center;align-items:center;flex-wrap:wrap;gap:12px;padding:24px;background:#f7f9fd;min-height:380px;max-height:640px;overflow:auto}.word-cloud button{background:none;border:0;padding:6px;cursor:pointer;line-height:1.3;border-radius:6px}.word-cloud button:hover,.word-cloud button:focus-visible{background:#e5edff;outline:2px solid #3269db}.source-card{border-bottom:1px solid #e6ebf1;padding:16px 0}blockquote{white-space:pre-wrap;margin:12px 0;border-left:3px solid #dce6f5;padding-left:12px;line-height:1.8}.context{white-space:pre-wrap}@media(max-width:900px){.word-layout{grid-template-columns:1fr}.word-cloud{min-height:240px}}</style>
